def f(N: int, inputs: List[Tuple[int, int]]) -> int:
    from collections import defaultdict

    edge_dict = defaultdict(list)

    for a, b in inputs:
        edge_dict[a].append(b)

    visited = set()
    def dfs(node, parent=None):
        visited.add(node)
        if len(edge_dict[node]) == 1 and edge_dict[node][0] == parent:
            return 1
        else:
            max_subtree = 0
            for child in edge_dict[node]:
                if child not in visited:
                    max_subtree = max(max_subtree, 1 + dfs(child, node))
            return max_subtree

    result = 0
    for node in range(N):
        if node not in visited:
            result = max(result, dfs(node))

    return result
